#define _DEFAULT_SOURCE
#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <unistd.h>

int main(void) {
    int fd = open("quotes.bin", O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }

    size_t len = 64 * 1024 * 1024;                 // 64 MiB mapping
    char *map = mmap(NULL, len, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) { perror("mmap"); return 1; }

    madvise(map, len, MADV_WILLNEED);              // hint: prefetch pages
    mlock(map, len);                               // pin resident (needs limits)

    long long checksum = 0;
    for (size_t i = 0; i < len; i += 4096)         // one touch per 4 KiB page
        checksum += map[i];                        // faults happen here if unpinned

    printf("checksum %lld\n", checksum);
    munlock(map, len);
    munmap(map, len);
    close(fd);
    return 0;
}
